use bevy::prelude::*;
use bevy_egui::{egui,EguiContexts,EguiPlugin,EguiPrimaryContextPass};
#[derive(Resource,Default)] struct HudInput([f32;2]);
use forge_engine::{Project,Simulation,project_point};
use std::path::PathBuf;
#[derive(Resource)] struct Game{project:Project,sim:Simulation}
#[derive(Component)] struct ObjectId(uuid::Uuid);
fn main(){let path=std::env::args_os().nth(1).map(PathBuf::from).unwrap_or_else(||PathBuf::from("project.forge.json"));let path=match path.canonicalize(){Ok(p)=>p,Err(e)=>{eprintln!("Project: {e}");return;}};let p=match Project::load(&path){Ok(p)=>p,Err(e)=>{eprintln!("{e}");return;}};let root=path.parent().unwrap().to_string_lossy().into_owned();App::new().insert_resource(Game{project:p.clone(),sim:Simulation::default()}).add_plugins(DefaultPlugins.set(AssetPlugin{file_path:root,..default()}).set(ImagePlugin::default_nearest()).set(WindowPlugin{primary_window:Some(Window{title:p.name.clone(),resolution:(p.settings.production.resolution[0] as f32,p.settings.production.resolution[1] as f32).into(),..default()}),..default()})).add_plugins(EguiPlugin::default()).init_resource::<HudInput>().add_systems(EguiPrimaryContextPass,hud).add_systems(Startup,setup).add_systems(Update,(tick,particle_render).chain()).run();}
fn setup(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>){commands.spawn(Camera2d);for o in &game.project.objects{if let Some(s)=&o.pro.sound{if !s.path.starts_with("assets/"){continue;}let bus=if s.music{game.project.settings.music}else{game.project.settings.sfx};let volume=(s.volume*bus*game.project.settings.master).clamp(0.,1.);let settings=if s.looping{PlaybackSettings::LOOP}else{PlaybackSettings::DESPAWN};commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(s.path.clone())),settings.with_volume(bevy::audio::Volume::Linear(volume))));}}for o in &game.project.objects{if o.camera{continue;}let mut sprite=Sprite::from_color(Color::srgba_u8(o.color[0],o.color[1],o.color[2],o.color[3]),Vec2::from_array(o.size));if let Some(path)=&o.sprite{sprite.image=assets.load(path.clone());}commands.spawn((sprite,Transform::default(),ObjectId(o.id)));}}
fn tick(mut commands:Commands,assets:Res<AssetServer>,time:Res<Time>,keys:Res<ButtonInput<KeyCode>>,pads:Query<&Gamepad>,hud:Res<HudInput>,mut game:ResMut<Game>,images:Res<Assets<Image>>,mut sprites:Query<(&ObjectId,&mut Transform,&mut Sprite),Without<Camera2d>>,mut cameras:Query<&mut Transform,With<Camera2d>>){let c=&game.project.settings.production.controls;let pressed=|s:&str,k|keys.pressed(forge_engine::keycode(s,k)) as i32;let mut d=[(pressed(&c.right,KeyCode::KeyD)-pressed(&c.left,KeyCode::KeyA)) as f32,(pressed(&c.up,KeyCode::KeyW)-pressed(&c.down,KeyCode::KeyS)) as f32];for pad in &pads{let dz=c.deadzone.clamp(0.,0.95);let axis=|a|{let v=pad.get(a).unwrap_or(0.);if v.abs()>dz{v}else{0.}};d[0]+=axis(GamepadAxis::LeftStickX);d[1]+=axis(GamepadAxis::LeftStickY);if pad.pressed(GamepadButton::South){d[1]=1.;}}for i in 0..2{d[i]=(d[i]+hud.0[i]).clamp(-1.,1.);}let g=&mut *game;g.sim.step(&mut g.project,time.delta_secs(),d);for o in &g.project.objects{if !o.camera&&!sprites.iter().any(|(id,_,_)|id.0==o.id){let mut s=Sprite::from_color(Color::WHITE,Vec2::from_array(o.size));if let Some(path)=&o.sprite{s.image=assets.load(path.clone());}commands.spawn((s,Transform::default(),ObjectId(o.id)));}}for (id,mut t,mut s) in &mut sprites{if let Some(o)=g.project.objects.iter().find(|o|o.id==id.0){let c=forge_engine::lit_color(o,&g.project);s.color=Color::srgba_u8(c[0],c[1],c[2],c[3]);let p=forge_engine::sprite_center(o,g.project.isometric);t.translation=Vec3::new(p[0],p[1],o.layer as f32*10.+if g.project.isometric{-p[1]*0.001}else{0.});t.rotation=Quat::from_rotation_z(o.rotation.to_radians());if o.sprite.is_some(){if let Some(img)=images.get(&s.image){let uv=o.animation.uv(g.sim.elapsed);let size=img.size().as_vec2();s.rect=Some(Rect::from_corners(Vec2::from_array(uv[0])*size,Vec2::from_array(uv[2])*size));}}}}if let Some(o)=g.project.objects.iter().find(|o|o.camera){let p=project_point(o.position,g.project.isometric);for mut t in &mut cameras{t.translation.x=p[0];t.translation.y=p[1];}}}

#[derive(Component)] struct ParticleVisual;
fn particle_render(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>,mut old:Query<(Entity,&mut Sprite,&mut Transform),With<ParticleVisual>>){let mut pool=old.iter_mut();let mut count=0;for o in &game.project.objects{for (p,size,c) in forge_engine::particles(o,game.sim.elapsed){if count>=4096{break;}count+=1;let p=project_point(p,game.project.isometric);let mut sprite=Sprite::from_color(Color::srgba_u8(c[0],c[1],c[2],c[3]),Vec2::splat(size));if let Some(path)=&o.production.particle_texture{if path.starts_with("assets/"){sprite.image=assets.load(path.clone());}}let t=Transform::from_xyz(p[0],p[1],o.layer as f32*10.+1.);if let Some((_,mut s,mut tr))=pool.next(){*s=sprite;*tr=t;}else{commands.spawn((ParticleVisual,sprite,t));}}}for (e,_,_) in pool{commands.entity(e).despawn();}}

fn hud(mut contexts:EguiContexts,game:Res<Game>,mut input:ResMut<HudInput>){input.0=[0.;2];let Ok(ctx)=contexts.ctx_mut()else{return;};let rect=ctx.screen_rect();for (i,w) in game.project.settings.widgets.iter().enumerate(){let pos=rect.min+egui::vec2(rect.width()*w.anchor[0],rect.height()*w.anchor[1]);egui::Area::new(egui::Id::new(("hud",i))).fixed_pos(pos).show(ctx,|ui|{if w.action=="label"{ui.label(&w.text);}else{let r=ui.add_sized(w.size,egui::Button::new(&w.text));if r.is_pointer_button_down_on(){match w.action.as_str(){"left"=>input.0[0]-=1.,"right"=>input.0[0]+=1.,"jump"=>input.0[1]=1.,_=>{}}}}});}}
